    "studio.prompt-builder.tips": "Faida kubwa zaidi",
    "studio.prompt-builder.howScored": "Alama zinahesabiwaje?",
    "studio.prompt-builder.howScoredBody": "Kipimo ni kanuni rahisi zinazoonekana, si AI inayohukumu. Kila kipimo kina alama 20. Kinatuza kile ambacho kwa kawaida hufanya prompt ifanye kazi: ukweli ambao modeli haiwezi kubahatisha, muundo wazi, na kuiomba modeli ionyeshe mashaka yake. Hakiwezi kujua kama ukweli wako ni sahihi. Wewe unaweza.",
    "studio.prompt-builder.preview": "Prompt yako",
    "studio.prompt-builder.previewEmpty": "(Ongeza vipande ili kujenga prompt yako.)",
    "studio.prompt-builder.check": "Kagua prompt yangu",
    "studio.prompt-builder.needBlocks": "Karibu! Jaza vipande hivi vinavyohitajika, bila [nafasi za kujaza] kubaki: {list}.",
    "studio.prompt-builder.needScore": "Prompt yako ina alama {score}. Unahitaji {n} kwa changamoto hii. Vidokezo vinaonyesha faida kubwa zaidi.",
    "studio.prompt-builder.resultScore": "Nguvu ya mwisho: {score}/100.",
    "studio.prompt-builder.realIntro": "Nakili prompt yako, ongeza maudhui yako halisi (kwa mfano barua pepe au maandishi ya sera) na uone msaidizi halisi anafanya nini nayo.",
    "studio.prompt-builder.clear": "Futa vipande vyote",
    "studio.prompt-builder.meter": "Nguvu ya prompt",
    "studio.prompt-builder.level.strong": "Imara",
    "studio.prompt-builder.level.ok": "Inakaribia",
    "studio.prompt-builder.level.weak": "Dhaifu",
