    "studio.prompt-builder.blk.role.name": "Jukumu",
    "studio.prompt-builder.blk.role.hint": "AI ifanye kazi kama nani? Mahususi na halisi ni bora kuliko 'gwiji wa dunia'.",
    "studio.prompt-builder.blk.role.tpl": "Wewe ni [jukumu mahususi] mwenye uzoefu katika [fani].",
    "studio.prompt-builder.blk.task.name": "Lengo / Kazi",
    "studio.prompt-builder.blk.task.hint": "Itoe nini hasa, na kwa nini?",
    "studio.prompt-builder.blk.task.tpl": "Kazi yako: [unachotaka kitolewe] ili [lengo].",
    "studio.prompt-builder.blk.context.name": "Muktadha",
    "studio.prompt-builder.blk.context.hint": "Ukweli ambao haiwezi kubahatisha: hali, historia, ulichokwisha jaribu.",
    "studio.prompt-builder.blk.context.tpl": "Historia: [kilichotokea, ukweli muhimu, nilichokwisha jaribu].",
    "studio.prompt-builder.blk.audience.name": "Hadhira",
    "studio.prompt-builder.blk.audience.hint": "Nani atasoma matokeo, na anahitaji nini?",
    "studio.prompt-builder.blk.audience.tpl": "Msomaji ni [nani], anayejua [anachojua] na anahitaji [anachohitaji].",
    "studio.prompt-builder.blk.constraints.name": "Masharti",
    "studio.prompt-builder.blk.constraints.hint": "Urefu, mtindo, ya kufanya na ya kuepuka.",
    "studio.prompt-builder.blk.constraints.tpl": "Chini ya maneno [idadi]. Usi[kitu cha kuepuka].",
    "studio.prompt-builder.blk.examples.name": "Mifano",
    "studio.prompt-builder.blk.examples.hint": "Onyesha jinsi kazi nzuri inavyoonekana.",
    "studio.prompt-builder.blk.examples.tpl": "Huu ni mfano wa ninachotaka: [mfano mfupi].",
    "studio.prompt-builder.blk.format.name": "Muundo wa jibu",
    "studio.prompt-builder.blk.format.hint": "Umbo la jibu: vitone, jedwali, sehemu.",
    "studio.prompt-builder.blk.format.tpl": "Muundo: [kwa mfano vitone 3, au jedwali lenye safu X, Y, Z].",
    "studio.prompt-builder.blk.checks.name": "Ukaguzi wa ubora",
    "studio.prompt-builder.blk.checks.hint": "Ifanye ionyeshe dhana na mashaka yake badala ya kujifanya inajua.",
    "studio.prompt-builder.blk.checks.tpl": "Kabla ya kujibu, orodhesha dhana zako. Taja chochote usicho na uhakika nacho na useme ni taarifa gani ingebadilisha jibu lako.",
    "studio.prompt-builder.blk.systems.name": "Mtazamo wa mfumo",
    "studio.prompt-builder.blk.systems.hint": "Ifanye ichore sehemu, mizunguko ya mrejesho na athari zinazofuata.",
    "studio.prompt-builder.blk.systems.tpl": "Chora sehemu zinazohusika, mizunguko ya mrejesho kati yake na athari za pili: nani mwingine wanaoathirika, na nini kinabadilika baadaye.",

    "studio.prompt-builder.tip.taskFilled": "Ongeza kipande cha Lengo / Kazi na useme hasa unachotaka kitolewe.",
    "studio.prompt-builder.tip.taskDetail": "Fanya kazi iwe mahususi: nini kitolewe na kwa lengo gani (maneno 10 au zaidi).",
    "studio.prompt-builder.tip.measurable": "Ongeza kitu kinachopimika: kikomo cha maneno, idadi ya hoja, tarehe ya mwisho.",
    "studio.prompt-builder.tip.noPlaceholders": "Badilisha kila [nafasi ya kujaza] kwa maelezo yako halisi.",
    "studio.prompt-builder.tip.contextFilled": "Ongeza muktadha: hali, kilichotokea, ulichokwisha jaribu.",
    "studio.prompt-builder.tip.contextDetail": "Toa muktadha zaidi (maneno 20 au zaidi): ukweli ambao AI haiwezi kubahatisha.",
    "studio.prompt-builder.tip.audienceFilled": "Sema nani atasoma na anahitaji nini.",
    "studio.prompt-builder.tip.roleFilled": "Ipe AI jukumu mahususi na halisi.",
    "studio.prompt-builder.tip.formatFilled": "Omba muundo wa jibu ili ulitumie kama lilivyo.",
    "studio.prompt-builder.tip.formatShape": "Taja umbo: vitone, jedwali lenye safu zenye majina, hatua zenye namba.",
    "studio.prompt-builder.tip.constraintsFilled": "Ongeza masharti: urefu, mtindo, cha kuepuka.",
    "studio.prompt-builder.tip.checksFilled": "Ongeza ukaguzi wa ubora ili AI ionyeshe dhana na mashaka yake.",
    "studio.prompt-builder.tip.checksKeywords": "Iombe iorodheshe dhana, ikadirie uhakika wake au itaje mashaka.",
    "studio.prompt-builder.tip.examplesFilled": "Onyesha mfano mfupi wa kazi nzuri.",
    "studio.prompt-builder.tip.systemsFilled": "Ongeza mtazamo wa mfumo: sehemu, mizunguko ya mrejesho, athari za pili.",
    "studio.prompt-builder.tip.systemsKeywords": "Uliza nani mwingine wanaoathirika na nini kinabadilika baadaye.",

    "studio.prompt-builder.crit.taskFilled": "Kipande cha Kazi kimejazwa",
    "studio.prompt-builder.crit.taskDetail": "Kazi ina maneno 10 au zaidi",
